import * as React from "react"

function HamburgerMenuWithHoverEffect({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="hamburger-menu-with-hover-effect"
      className={className}
      {...props}
    >
      <div
          className="group flex h-20 w-20 cursor-pointer items-center justify-center rounded-3xl bg-white p-2 hover200">
          <div className="space-y-2">
              <span className="block h-1 w-10 origin-center rounded-full bg-slate-500 transition-transform ease-in-out group-hover1.5 group-hover45"></span>
              <span className="block h-1 w-8 origin-center rounded-full bg-orange-500 transition-transform ease-in-out group-hover10 group-hover1.5 group-hover45"></span>
          </div>
      </div>
    </div>
  )
}

export { HamburgerMenuWithHoverEffect }
